import{i as e,u as t,v as n,y as r}from"./index-BPzRJPxW.js";var i={id:2,kicker:`AI isn’t one machine — it’s a whole tree with many branches.`,summary:`AI is a tree with many branches; chatbots are just one small twig.`,quiz:{q:`Your next TikTok video always seems oddly perfect for you. Which branch picks it?`,options:[`Recognition / classification AI`,`Recommendation AI`,`Generative AI`,`Robots / physical AI`],answer:1,explain:`That’s recommendation AI: it doesn’t make new videos, it picks from existing ones the video you’re most likely to keep watching.`},scenes:{seed:{label:`Plant a seed`,prompt:`Tap to water`,water:`Water the seed`,again:`Water the tree again`,art:`Ink painting: a shallow bonsai pot, a seed resting on the soil, raked sand below, a pale sun behind.`,rootLabel:`machine learning`,insight:`Most AI you meet every day grows from one root: machine learning — computers drawing patterns from many examples.`,detail:`Unlike regular software, no one writes each rule by hand, so it guesses very well but is sometimes wrong.`},branches:{label:`The branches`,prompt:`Tap a crown of leaves`,art:`Ink painting: a bonsai with four leafy crowns, each one a family of AI; tap a crown and an ink-drawn fruit hangs down: a persimmon with an eye, a bunch of berries with one ripe red, a small robot arm picking fruit. The top crown is generative AI: a young apricot-blossom branch grows six flowers, and tapping each one makes the brush paint a small picture.`,padAria:`{name} crown — see explanation`,twigAria:`{name} flower on the young generative AI branch — see explanation`,done:`One root, many branches`,families:[{id:`recog`,short:`Recognition AI`,name:`Recognition / classification AI`,insight:`Recognition AI looks, listens, then files things in the right box — like unlocking your phone with your face, or filtering spam.`,detail:`It creates nothing new; it just answers: what is this, who is it, what kind is it.`},{id:`rec`,short:`Recommendation AI`,name:`Recommendation AI`,insight:{text:`Recommendation AI guesses what you’ll probably like next — like your next TikTok video, or a product on Shopee.`,asOf:`2026-10-12`,source:`brief-2026-10-12`},detail:{text:`TikTok says it picks videos based on what you like, share, comment on and watch to the end.`,asOf:`2026-10-12`,source:`tiktok-foryou`}},{id:`gen`,short:`Generative AI`,name:`Generative AI`,insight:`Generative AI makes something new: type a description, get back text or an image that never existed before.`,detail:`The chatbot you use is just one twig on this branch, alongside images, video, audio, 3D and code.`},{id:`robot`,short:`Robot`,name:`Robots / physical AI`,insight:`Robots are AI with a body: they see through cameras, move around, grab things — like a robot vacuum dodging chair legs.`,detail:`Robot arms in warehouses do the same: recognize an item, then grab it in the right place.`}],twigs:[{id:`text`,name:`Text (LLM)`,insight:`An LLM — large language model — reads huge amounts of text to learn how to keep writing, one small piece at a time.`,detail:{text:`ChatGPT, a chatbot on this branch, launched on November 30, 2022.`,asOf:`2026-10-12`,source:`openai-chatgpt`}},{id:`image`,name:`Images`,insight:`Turns a description into a brand-new image, or edits part of an existing one.`,detail:`Example: type “a cat in a conical hat by a lotus pond” and get back an image that never existed.`},{id:`video`,name:`Video`,insight:`Makes a short video clip from a description, or from a single photo.`,detail:`Example: turn a product photo into a short ad clip.`},{id:`audio`,name:`Sound, music, voice`,insight:`Reads text aloud in a natural voice, composes music, or makes sound effects for video.`,detail:`Example: turn an article into a read-aloud that sounds like a podcast.`},{id:`3d`,name:`3D models`,insight:`Creates 3D objects you can spin to see from every side, from a description or a photo.`,detail:`Example: from a photo of a chair, make a 3D model to try out in a virtual room.`},{id:`code`,name:`Code (programming)`,insight:`Writes and fixes code — the lines of instructions behind software, apps and websites.`,detail:`Example: describe an event sign-up page in words, and AI writes the code for you.`}]}},sources:{"openai-chatgpt":{title:`Introducing ChatGPT`,publisher:`OpenAI`,url:`https://openai.com/index/chatgpt/`,date:`2022-11-30`},"tiktok-foryou":{title:`How TikTok recommends videos #ForYou`,publisher:`TikTok Newsroom`,url:`https://newsroom.tiktok.com/how-tiktok-recommends-videos-for-you?lang=en`,date:`2020-06-18`,note:`TikTok’s own post explaining how it picks videos for the For You page.`}}};function a(e){if(e=e.trim(),e.startsWith(`#`)){let t=e.slice(1);t.length<=4&&(t=[...t].map(e=>e+e).join(``));let n=parseInt(t.slice(0,6),16);return[n>>16&255,n>>8&255,n&255]}let t=e.match(/[\d.]+/g);return t?[+t[0],+t[1],+t[2]]:[0,0,0]}var o=(e,t,n)=>[e[0]+(t[0]-e[0])*n,e[1]+(t[1]-e[1])*n,e[2]+(t[2]-e[2])*n],s=(e,t=1)=>`rgba(${e[0]|0},${e[1]|0},${e[2]|0},${+t.toFixed(3)})`;function c(e){let t=e>>>0;return()=>{t=t+1831565813>>>0;let e=t;return e=Math.imul(e^e>>>15,e|1),e^=e+Math.imul(e^e>>>7,e|61),((e^e>>>14)>>>0)/4294967296}}function l(e){let t=c(e),n=Array.from({length:256},t);return e=>{let t=Math.floor(e),r=e-t,i=n[t&255];return i+(n[t+1&255]-i)*r*r*(3-2*r)}}var u=(e,t=0,n=1)=>Math.max(t,Math.min(n,e)),d=(e,t,n)=>{let r=u((n-e)/(t-e));return r*r*(3-2*r)};function f(e,t){let n=[];for(let t=0;t<e.length-1;t++){let r=e[Math.max(0,t-1)],i=e[t],a=e[t+1],o=e[Math.min(e.length-1,t+2)];for(let e=0;e<24;e++){let t=e/24,s=t*t,c=s*t,l=(e,n,r,i)=>.5*(2*n+(-e+r)*t+(2*e-5*n+4*r-i)*s+(-e+3*n-3*r+i)*c);n.push({x:l(r.x,i.x,a.x,o.x),y:l(r.y,i.y,a.y,o.y)})}}n.push(e[e.length-1]);let r=[n[0]],i=0;for(let e=1;e<n.length;e++){let a=n[e-1],o=n[e],s=Math.hypot(o.x-a.x,o.y-a.y),c=a;for(;i+s>=t;){let e=(t-i)/s,n={x:c.x+(o.x-c.x)*e,y:c.y+(o.y-c.y)*e};r.push(n),s-=t-i,c=n,i=0}i+=s}let a=n[n.length-1];return Math.hypot(a.x-r[r.length-1].x,a.y-r[r.length-1].y)>t*.3&&r.push(a),r}functi